      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "དོ་ཧར།",
      "head": "ཡུལ་རྣམས་བརྟེན་ཀྱང་ཡུལ་གྱིས་མི་གོས་ཏེ། །ཨུཏྤལ་འདབ་མ་ཆུ་ཡིས་མི་གོས་ཤིང་། །གང་ལ་རྩ་བ་རྣལ་འབྱོར་སྐྱབས་འགྲོ་དང་༑ །དུག་གི་སྔགས་ཅན་དུག་གིས་ག་ལ་ཚུགས། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "འཕགས་པ་དཀོན་མཆོག་བརྩེགས་པའི་ཆོས་ཀྱི་རྣམ་གྲངས་ལས།",
      "head": "དེ་ལྟར་སེམས་ཡོངས་སུ་འཚོལ་ཏེ། ཅི་འདས་པའམ། མ་འོངས་པའམ། ད་ལྟར་བྱུང་བ་ཞིག་གམ། དེ་ལ་འདས་པའི་སེམས་གང་ཡིན་པ་ནི་ཟད་པའོ། མ་འོངས་པ་གང་ཡིན་པ་ནི་མ་སྐྱེས་པའོ། །ད་ལྟར་བྱུང་བ་ནི་གནས་པ་མེད་དོ༑ །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "སེམས་ནི་ཀུན་ཏུ་མི་དམིགས་སོ། །གང་མི་དམིགས་པ་དེ་ནི་འདས་པ་མ་ཡིན་ནོ། །མ་འོངས་པ་མ་ཡིན་ནོ༑ ད་ལྟར་བྱུང་བ་མ་ཡིན་ནོ༑ །གང་འདས་པ་མ་ཡིན། མ་འོངས་པ་མ་ཡིན། ད་ལྟར་བྱུང་བ་མ་ཡིན་པ་དེ་ནི་དུས་གསུམ་ལས་ཡང་དག་པར་འདས་པའོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཤ་ཝ་རིས།",
      "head": "མི་དམིགས་དུས་གསུམ་མ་སྐྱེས་འགག་པ་མེད། །དེ་ཉིད་གཞན་དུ་འགྱུར་བ་མེད་པ་ནི། །རང་བཞིན་བདེ་བ་ཆེན་པོའི་གནས་ལུགས་ཡིན། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཐོག་མཐའ་མེད་པའི་སེམས་དཔའ་ནི། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཐོག་མ་མཐའ་མ་མེད་ཞི་བ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "དཔལ་ས་ར་ཧས།",
      "head": "དངོས་པོར་སྐྱེ་བ་མཁའ་ལྟར་རབ་ཞི་ནས། །དངོས་པོ་རྣམས་སྤངས་ཕྱི་ནས་ཅི་ཞིག་སྐྱེ། །གདོད་ནས་སྐྱེ་མེད་རང་བཞིན་ཡིན་པ་ལ། །དེ་རིང་བླ་མ་མགོན་པོས་བསྟན་པས་རྟོགས༑ །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "དཔལ་ཤ་ཝ་རས།",
      "head": "སེམས་ཡོད་གྱུར་ན་ཆོས་ཀུན་ཡོད་རིགས་ཏེ། །སེམས་མེད་པ་ལས་ཆོས་ཤིག་སུ་ཡིས་རྟོགས།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "ཀླུའི་རྒྱལ་པོ་མ་དྲོས་པས་ཞུས་པའི་མདོར།",
      "head": "གང་ཞིག་ལམ་ནི་དངོས་བྱེད་མིན། །དངོས་མེད་དངོས་པོ་མེད་བྱེད་མིན། །དངོས་དང་དངོས་མེད་བྲལ་བ་ནི། །མཆོག་གི་ལམ་གང་བསྒོམ་པའོ༑ །བཅོམ་ལྡན་དངོས་དང་དངོས་མེད་པ། །མཁྱེན་པས་ཀ་ཏྱ་ཡ་ཎ་ཡི། །གདམས་ངག་ལས་ནི་ཡོད་པ་དང་། །མེད་པ་གཉིས་ཀ་བཀག་པར་མཛད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "བྲམ་ཟེ་ཆེན་པོས།",
      "head": "ལྷན་ཅིག་སྐྱེས་པའི་རང་བཞིན་དེ་ཉིད་ནི། །དངོས་དང་དངོས་པོ་མེད་པ་མ་ཡིན་ཞེས། །མདའ་བསྣུན་རྟག་ཏུ་འོ་དོད་འབོད་པར་བྱེད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "རྗེ་མི་ལས།",
      "head": "སེམས་འགྱུ་བ་དངོས་མེད་སྟོང་པ་འདི། །འདྲེ་ཁྱོད་པས་ངས་ཀྱང་མཐོང་བ་མེད༑ །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "སློབ་དཔོན་ཀླུས།",
      "head": "གང་གི་རྟེན་ཅིང་འབྲེལ་བར་འབྱུང་། །འགག་པ་མེད་པ་སྐྱེ་མེད་པ༑ །ཆད་པ་མེད་པ་རྟག་མེད་པ། །འོང་བ་མེད་པ་འགྲོ་མེད་པ། །ཐ་དད་དོན་མིན་དོན་གཅིག་མིན། སྤྲོས་པ་ཉེར་ཞི་ཞིར་བསྟན་པ། །རྫོགས་པའི་སངས་རྒྱས་སྨྲ་རྣམས་ཀྱི། །དམ་པ་དེ་ལ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "བླ་མའི་ངག་གིས་མ་བརྒྱན་པའི། །དབུ་མའང་འབྲིང་པོ་ཙམ་ཉིད་དེ། །བླ་མས་སྨྲས་པ་གང་གི་སྙིང་ཞུགས་པ། །ལག་པའི་མཐིལ་དུ་གནས་པའི་གཏེར་མཐོང་འདྲ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "དབུ་མའི་མན་ངག་ལས།",
      "head": "འདི་ལྟར་ནམ་མཁའ་དང་འདྲ་བས་སམ་གྲུབ་པའམ་ཡང་ན་གཅིག་དང་དུ་མ་དང་བྲལ་བས་སམ། མ་སྐྱེས་པ་དང་དེའི་རང་བཞིན་འོད་གསལ་བ་ལ་སོགས་པ་རིག་པས་དཔྱད་ཅིང་གཞིག་པས་མ་གྲུབ་པར་ཤེས་སོ། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "དོ་ཧར།",
      "head": "གཉིས་སུ་མི་བྱ་གཅིག་ཏུ་བྱ་བ་སྟེ། །རིགས་དང་བྱེ་བྲག་དག་ཏུ་མ་འབྱེད་ཅིག །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "སེམས་ཉིད་གཅིག་པུ་ཀུན་གྱི་ས་བོན་ཏེ།",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "བྲམ་ཟེ་ཆེན་པོས།",
      "head": "ཀྱེ་མ་རང་ལ་རང་གིས་དེ་ཉིད་མཚོན་ཏེ་ལྟོས། །མ་ཡེངས་སེམས་ཀྱིས་བལྟ་དང་བྲལ་གྱུར་ན། །ཡེངས་པའི་སེམས་ཀྱིས་དེ་ཉིད་མཐོང་བ་མེད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "ཕུང་པོ་རྣམ་དཔྱད་སྟོང་པ་ཉིད། །ཆུ་ཤིང་བཞིན་དུ་སྙིང་པོ་མེད། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "head": "དེ་ལྟར་སེམས་ཡོངས་སུ་ཚོལ་ཏེ་",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "གཙུག་ན་རིན་པོ་ཆེའི་མདོ་ལས།",
      "head": "དེ་སེམས་ཀུན་ཏུ་འཚོལ་བ་ནི། །",
      "tail": ""
    },
    {
      "label": "QUOTE",
      "frame": "སུམ་ཅུ་རྩ་གསུམ་པའི་ལེའུ་ལས་ཀྱང་།",
      "head": "མཁས་པ་དེ་ཉིད་སེམས་ཀྱི་ཆོས་ཉིད་ཚོལ། །དེ་ནི་སེམས་ཀྱི་ཆོས་ཉིད་ཚོལ་བ་ན། །སེམས་དང་སེམས་ཀྱི་ཆོས་ཉིད་མཐོང་བ་ན། །སེམས་དེ་སེམས་གང་གིས་ནི་ཚོལ་བྱེད་པ། །སེམས་དེ་ཡང་ནི་རང་བཞིན་མཐོང་བ་མེད། །",
      "tail": ""
    },
    {
